style.css:
/* Hide default Google logo image */
img[alt="Google"] {
  display: none !important;
}

/* Show custom text instead */
body::after {
  content: "Google";
  font-size: 92px;
  font-family: Arial, sans-serif;
  color: #ffcadd;
  position: absolute;
  top: 180px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9999;
}
